window.LESSON_DATA = {"schemaVersion":"1.0.0","version":"1.0.1","buildDate":"2026-07-29","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.1","slug":"standard-form","title":"Scientific Notation and Orders of Magnitude","subtitle":"Represent very large and very small quantities efficiently, calculate with powers of ten, and interpret scale.","syllabus_focus":"SL 1.1 — Operations with numbers in the form a × 10^k, where 1 ≤ a < 10 and k is an integer.","skill_keys":["IBAI.U1.NUMBER","IBAI.U1.MODELING"],"objectives":["Convert fluently between ordinary notation and standard form.","Multiply, divide, add and subtract quantities written with powers of ten.","Use order of magnitude to compare scales and test the reasonableness of a result.","Communicate units, precision and interpretation in authentic scientific and social contexts."],"vocab":["standard form","coefficient","power of ten","integer exponent","order of magnitude","scale","reasonable estimate"],"technology":"Use the calculator scientific-notation key, but read the display structurally: coefficient first, exponent second. Test a result with a one-significant-figure estimate.","transition":"This lesson remains central in both the current course and the first-assessment-2029 course."},"slides":[{"section":"Launch","title":"1.1 · Scientific Notation and Orders of Magnitude","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB DP Mathematics · Applications and Interpretation SL</div><h1><span class=\"cover-number\">1.1</span>Scientific Notation and Orders of Magnitude</h1><p class=\"cover-subtitle\">Represent very large and very small quantities efficiently, calculate with powers of ten, and interpret scale.</p><div class=\"pill-row\"><span>Current syllabus</span><span>Technology-rich</span><span>Modelling</span><span>Original practice</span></div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"cover","eyebrow":"Unit 1 · Number and Algebra"},{"section":"Launch","title":"Your place in Unit 1","html":"<div class=\"unit-map\"><div class=\"map-node active\"><b>1.1</b><span>Scientific Notation and Orders of Magnitude</span></div><div class=\"map-node \"><b>1.2</b><span>Arithmetic Sequences and Series</span></div><div class=\"map-node \"><b>1.3</b><span>Geometric Sequences and Series</span></div><div class=\"map-node \"><b>1.4</b><span>Financial Applications of Sequences</span></div><div class=\"map-node \"><b>1.5</b><span>Introduction to Logarithms</span></div><div class=\"map-node \"><b>1.6</b><span>Approximation, Bounds and Percentage Error</span></div><div class=\"map-node \"><b>1.7</b><span>Loans, Annuities and Amortization</span></div><div class=\"map-node \"><b>1.8</b><span>Technology for Equations and Systems</span></div></div><p class=\"callout\">The course moves from representation and discrete change to financial modelling, uncertainty and technology-based solution methods.</p>","kind":"content","eyebrow":""},{"section":"Launch","title":"Syllabus focus","html":"<div class=\"focus-card\"><h3>Current course alignment</h3><p>SL 1.1 — Operations with numbers in the form a × 10^k, where 1 ≤ a < 10 and k is an integer.</p><p><b>Platform mastery keys:</b> IBAI.U1.NUMBER, IBAI.U1.MODELING</p></div><div class=\"transition-note\">This lesson remains central in both the current course and the first-assessment-2029 course.</div>","kind":"content","eyebrow":""},{"section":"Inquiry","title":"A question worth investigating","html":"<blockquote>How can one compact notation make quantities from cells to galaxies comparable?</blockquote><p>Record an initial response. Return to it at the end and identify how your reasoning changed.</p><textarea class=\"student-note\" data-note=\"inquiry\" aria-label=\"Inquiry response\"></textarea>","kind":"inquiry","eyebrow":""},{"section":"Inquiry","title":"Learning intentions","html":"<div class=\"two-col\"><div><h3>By the end, you can…</h3><ul class=\"check-list\"><li>Convert fluently between ordinary notation and standard form.</li><li>Multiply, divide, add and subtract quantities written with powers of ten.</li><li>Use order of magnitude to compare scales and test the reasonableness of a result.</li><li>Communicate units, precision and interpretation in authentic scientific and social contexts.</li></ul></div><div><h3>Evidence of understanding</h3><ul class=\"check-list\"><li>Choose an efficient representation.</li><li>Use technology transparently.</li><li>Interpret rather than merely calculate.</li><li>Evaluate assumptions and precision.</li></ul></div></div>","kind":"content","eyebrow":""},{"section":"Diagnostic","title":"Prior-knowledge diagnostic","html":"<div class=\"student-turn\"><h3>Try before instruction</h3><p>Without a calculator, estimate \\(\\frac{6.2\\times10^7}{3.1\\times10^3}\\). Explain how the exponent predicts the scale of the answer.</p><textarea class=\"student-note\" data-note=\"diagnostic\"></textarea><details><summary>Diagnostic lens</summary><p>Focus on structure, units and the meaning of the result—not just a final number.</p></details></div>","kind":"student","eyebrow":""},{"section":"Language","title":"Core vocabulary","html":"<div class=\"vocab-grid\"><div class=\"vocab-chip\">standard form</div><div class=\"vocab-chip\">coefficient</div><div class=\"vocab-chip\">power of ten</div><div class=\"vocab-chip\">integer exponent</div><div class=\"vocab-chip\">order of magnitude</div><div class=\"vocab-chip\">scale</div><div class=\"vocab-chip\">reasonable estimate</div></div><p class=\"callout\">Use precise vocabulary in every explanation. In IB mathematics, communication earns meaning, not decoration.</p>","kind":"content","eyebrow":""},{"section":"Approach","title":"The AI modelling cycle","html":"<div class=\"cycle\"><div>Context</div><span>→</span><div>Assumptions</div><span>→</span><div>Mathematical form</div><span>→</span><div>Technology & computation</div><span>→</span><div>Interpretation</div><span>→</span><div>Validation & refinement</div></div><p>Every substantial task in this lesson returns to this cycle. A numerical answer without interpretation is unfinished.</p>","kind":"content","eyebrow":""},{"section":"Concept 1","title":"The normalized form","html":"<div class=\"concept-grid\"><div><p>A non-zero number is in standard form when it is written as \\(a\\times10^k\\), with \\(1\\le |a|<10\\) and integer \\(k\\). The coefficient records significant digits; the exponent records scale.</p><div class=\"formula-panel\">\\[N=a\\times10^k,\\qquad 1\\le |a|<10\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"content","eyebrow":"Concept cycle 1 of 5"},{"section":"Concept 1","title":"Worked example · The normalized form","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Write \\(0.000438\\) in standard form.</p></div><div class=\"method\"><span>Reasoning</span><p>Move the decimal four places right: \\(0.000438=4.38\\times10^{-4}\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 1","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Write \\(72\\,900\\,000\\) in standard form.</p><textarea class=\"student-note\" data-note=\"turn-1\"></textarea><details><summary>Reveal answer and check</summary><p>\\(7.29\\times10^7\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 1","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(7.29\\times10^7\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>\\(72.9\\times10^6\\) has the correct value but is not normalized because the coefficient exceeds 10.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 2","title":"Moving between forms","html":"<div class=\"concept-grid\"><div><p>A positive exponent moves the decimal point right when expanding; a negative exponent moves it left. Keep zeros as place holders, not as new significant digits.</p><div class=\"formula-panel\">\\[3.06\\times10^{-5}=0.0000306\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"content","eyebrow":"Concept cycle 2 of 5"},{"section":"Concept 2","title":"Worked example · Moving between forms","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Expand \\(8.021\\times10^6\\).</p></div><div class=\"method\"><span>Reasoning</span><p>Move six places right: \\(8\\,021\\,000\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 2","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Expand \\(5.7\\times10^{-3}\\).</p><textarea class=\"student-note\" data-note=\"turn-2\"></textarea><details><summary>Reveal answer and check</summary><p>\\(0.0057\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 2","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(0.0057\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The sign of the exponent describes scale, not the sign of the number.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 3","title":"Multiplication and division","html":"<div class=\"concept-grid\"><div><p>Operate on coefficients and powers separately, then renormalize. Exponents add under multiplication and subtract under division.</p><div class=\"formula-panel\">\\[(a\\times10^m)(b\\times10^n)=ab\\times10^{m+n}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"content","eyebrow":"Concept cycle 3 of 5"},{"section":"Concept 3","title":"Worked example · Multiplication and division","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Calculate \\((4.8\\times10^7)(2.5\\times10^{-3})\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(4.8(2.5)\\times10^4=12\\times10^4=1.2\\times10^5\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 3","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Calculate \\(\\frac{9.6\\times10^{-4}}{3.2\\times10^2}\\).</p><textarea class=\"student-note\" data-note=\"turn-3\"></textarea><details><summary>Reveal answer and check</summary><p>\\(3\\times10^{-6}\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 3","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(3\\times10^{-6}\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Do not multiply exponents. The laws of indices determine how exponents combine.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 4","title":"Addition and subtraction","html":"<div class=\"concept-grid\"><div><p>Before adding or subtracting, rewrite quantities using a common power of ten. Only then combine coefficients.</p><div class=\"formula-panel\">\\[4.2\\times10^5+7.0\\times10^4=(4.2+0.70)\\times10^5\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"content","eyebrow":"Concept cycle 4 of 5"},{"section":"Concept 4","title":"Worked example · Addition and subtraction","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Calculate \\(6.3\\times10^8-4.7\\times10^7\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\((6.3-0.47)\\times10^8=5.83\\times10^8\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 4","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Calculate \\(2.4\\times10^{-3}+8.0\\times10^{-4}\\).</p><textarea class=\"student-note\" data-note=\"turn-4\"></textarea><details><summary>Reveal answer and check</summary><p>\\(3.2\\times10^{-3}\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 4","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(3.2\\times10^{-3}\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Adding exponents is valid for multiplication, not for addition.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 5","title":"Order of magnitude and interpretation","html":"<div class=\"concept-grid\"><div><p>Order of magnitude compares scales approximately. After calculating, ask whether the coefficient, exponent and units make sense in context.</p><div class=\"formula-panel\">\\[\\text{order of magnitude}\\approx10^{\\operatorname{round}(\\log_{10}|N|)}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Orders of magnitude scale\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"34\" font-weight=\"800\" fill=\"#17324D\">Orders of magnitude</text><line x1=\"55\" y1=\"98\" x2=\"455\" y2=\"98\" stroke=\"#17324D\" stroke-width=\"4\"/><circle cx=\"70\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"70\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-6</tspan></text><circle cx=\"165\" cy=\"98\" r=\"7\" fill=\"#D4A72C\"/><text x=\"165\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">-3</tspan></text><circle cx=\"260\" cy=\"98\" r=\"7\" fill=\"#7A1733\"/><text x=\"260\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">0</tspan></text><circle cx=\"355\" cy=\"98\" r=\"7\" fill=\"#17324D\"/><text x=\"355\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">3</tspan></text><circle cx=\"450\" cy=\"98\" r=\"7\" fill=\"#177E89\"/><text x=\"450\" y=\"130\" text-anchor=\"middle\">10<tspan dy=\"-6\" font-size=\"11\">6</tspan></text><path d=\"M70 62 L450 62\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/><text x=\"260\" y=\"57\" text-anchor=\"middle\" fill=\"#7A1733\">Each step changes scale by ×1000</text></svg></div>","kind":"content","eyebrow":"Concept cycle 5 of 5"},{"section":"Concept 5","title":"Worked example · Order of magnitude and interpretation","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>A dataset has \\(3.2\\times10^6\\) rows of \\(2.5\\times10^2\\) bytes each. Estimate its size.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(8.0\\times10^8\\) bytes, about \\(0.8\\) GB in decimal units.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 5","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>A population grows from \\(4.0\\times10^5\\) to \\(1.2\\times10^6\\). By what factor did it grow?</p><textarea class=\"student-note\" data-note=\"turn-5\"></textarea><details><summary>Reveal answer and check</summary><p>A factor of \\(3\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 5","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>A factor of \\(3\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>An exponent difference of 2 means a factor of about \\(10^2=100\\), not a difference of 2.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Technology","title":"Interactive exploration","html":"<div id=\"lesson-lab\" class=\"lab\" data-lab=\"1.1\"></div><p class=\"lab-note\">Change more than one input. Predict before pressing calculate, then explain what stays invariant.</p>","kind":"lab","eyebrow":""},{"section":"Technology","title":"Transparent technology workflow","html":"<div class=\"workflow\"><div><b>1</b> Define variables and domain</div><div><b>2</b> Enter the mathematical model</div><div><b>3</b> Choose an appropriate tool</div><div><b>4</b> Record settings/output</div><div><b>5</b> Verify independently</div><div><b>6</b> Interpret and round</div></div><p>Use the calculator scientific-notation key, but read the display structurally: coefficient first, exponent second. Test a result with a one-significant-figure estimate.</p>","kind":"content","eyebrow":""},{"section":"Application","title":"Global and local context","html":"<div class=\"context-card\"><span>Context challenge</span><p>Estimate the number of litres of water used by a school community in one academic year, state assumptions, and express the result in standard form.</p></div><textarea class=\"student-note tall\" data-note=\"context\"></textarea>","kind":"student","eyebrow":""},{"section":"Inquiry","title":"Mini-investigation","html":"<div class=\"investigation\"><h3>Question → evidence → conclusion</h3><p>Choose a quantity spanning at least six orders of magnitude. Build a scale diagram, justify data choices, and explain one surprising comparison.</p><ul class=\"check-list\"><li>State the question and variables.</li><li>Record assumptions and data sources.</li><li>Show mathematics and technology output.</li><li>Interpret, evaluate and refine.</li></ul></div>","kind":"investigation","eyebrow":""},{"section":"Assessment","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Write down</b><span>Give the result with little or no working.</span></div><div><b>Calculate</b><span>Show enough method for the result to be reproducible.</span></div><div><b>Determine</b><span>Reach a result with supporting reasoning.</span></div><div><b>Explain</b><span>Give causes, mechanisms or mathematical meaning.</span></div><div><b>Interpret</b><span>Translate mathematics back into context.</span></div><div><b>Comment</b><span>Make a judgement supported by evidence.</span></div></div>","kind":"content","eyebrow":""},{"section":"Assessment","title":"Solar data archive","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 1-style short response</span><span>8 marks</span><span>GDC expected</span></div><h3>Solar data archive</h3><p>A satellite stores \\(3.6\\times10^5\\) images. Each image requires \\(2.4\\times10^6\\) bytes.</p><div class=\"task-part\"><b>(a)</b> Calculate the total storage in bytes, giving your answer in standard form. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> A compression system reduces storage by 37%. Find the compressed storage in bytes in standard form. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> The archive is copied at \\(1.5\\times10^8\\) bytes per second. Find the transfer time in minutes. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> State one reason the calculated time may differ from real transfer time. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Solar data archive · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Solar data archive — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(8.64\\times10^{11}\\) bytes</b><p>M1 multiplies the two quantities and applies exponent law; A1 normalized result.</p></div><div class=\"solution-part\"><b>(b) \\(5.4432\\times10^{11}\\) bytes</b><p>M1 uses multiplier 0.63; A1 correct value.</p></div><div class=\"solution-part\"><b>(c) \\(60.48\\) minutes</b><p>M1 divides storage by rate; A1 seconds \\(3628.8\\); A1 converts to minutes.</p></div><div class=\"solution-part\"><b>(d) Protocol overhead, variable transfer rate or interruptions.</b><p>A1 one relevant modelling limitation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Assessment","title":"Water-use estimation","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 2-style extended response</span><span>10 marks</span><span>GDC expected</span></div><h3>Water-use estimation</h3><p>A campus has 1450 people. A preliminary model assumes each person uses \\(1.8\\times10^2\\) L of water per day on 210 operating days each year.</p><div class=\"task-part\"><b>(a)</b> Estimate annual water use in litres and write it in standard form. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(b)</b> Convert the answer to cubic metres, using \\(1\\text{ m}^3=10^3\\text{ L}\\). <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> A conservation plan targets a 12% reduction. Calculate the target annual use in cubic metres. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(d)</b> Give two assumptions that should be tested before using the model for budgeting. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(e)</b> Explain why reporting the target to the nearest litre would be misleading. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Water-use estimation · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Water-use estimation — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(5.481\\times10^7\\) L</b><p>M1 forms \\(1450(180)(210)\\); A1 evaluates; A1 standard form with units.</p></div><div class=\"solution-part\"><b>(b) \\(5.481\\times10^4\\text{ m}^3\\)</b><p>M1 divides by \\(10^3\\); A1 correct standard form.</p></div><div class=\"solution-part\"><b>(c) \\(48\\,232.8\\text{ m}^3\\)</b><p>M1 uses multiplier 0.88; A1 correct value.</p></div><div class=\"solution-part\"><b>(d) Examples: equal use per person; exactly 210 days; no leakage/irrigation variation; stable population.</b><p>A1 each for two distinct assumptions.</p></div><div class=\"solution-part\"><b>(e) The assumptions and input estimates do not justify that precision.</b><p>A1 links reporting precision to model uncertainty.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Connections","title":"Where this mathematics connects","html":"<div class=\"connection-grid\"><div>Measurement and uncertainty</div><div>Exponential models</div><div>Data storage and scientific scales</div><div>Fermi estimation</div></div><p>Write one sentence describing a connection you did not see at the start.</p><textarea class=\"student-note\" data-note=\"connection\"></textarea>","kind":"content","eyebrow":""},{"section":"Synthesis","title":"Five ideas to retain","html":"<ul class=\"check-list\"><li>The normalized form: A non-zero number is in standard form when it is written as \\(a\\times10^k\\), with \\(1\\le |a|<10\\) and integer \\(k\\).</li><li>Moving between forms: A positive exponent moves the decimal point right when expanding; a negative exponent moves it left.</li><li>Multiplication and division: Operate on coefficients and powers separately, then renormalize.</li><li>Addition and subtraction: Before adding or subtracting, rewrite quantities using a common power of ten.</li><li>Order of magnitude and interpretation: Order of magnitude compares scales approximately.</li></ul>","kind":"summary","eyebrow":""},{"section":"Reflection","title":"Return to the inquiry question","html":"<blockquote>How can one compact notation make quantities from cells to galaxies comparable?</blockquote><textarea class=\"student-note tall\" data-note=\"reflection\"></textarea><div class=\"reflection-grid\"><label><input type=\"checkbox\" data-reflect=\"model\"> I can model</label><label><input type=\"checkbox\" data-reflect=\"calculate\"> I can calculate</label><label><input type=\"checkbox\" data-reflect=\"interpret\"> I can interpret</label><label><input type=\"checkbox\" data-reflect=\"evaluate\"> I can evaluate</label></div>","kind":"reflection","eyebrow":""},{"section":"Exit","title":"Exit ticket","html":"<div class=\"exit-grid\"><div><b>One calculation</b><p>Create and solve a new example using today’s central formula.</p></div><div><b>One explanation</b><p>Describe a common error and how to detect it.</p></div><div><b>One evaluation</b><p>State one assumption that could change a conclusion.</p></div></div><textarea class=\"student-note tall\" data-note=\"exit\"></textarea>","kind":"student","eyebrow":""},{"section":"Next","title":"Practice Studio","html":"<div class=\"launch-panel\"><h2>40 original questions</h2><p>Four levels: Foundation, Application, Reasoning and Challenge. Every item includes marks, calculator guidance, hints and a complete solution.</p><button class=\"route-jump\" data-go=\"practice\">Open Practice Studio</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Independent timed quiz","html":"<div class=\"launch-panel\"><h2>10 fresh questions</h2><p>Complete the quiz under a suggested 25-minute timer, then review explanations and update your mastery reflection.</p><button class=\"route-jump\" data-go=\"quiz\">Start timed quiz</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Authenticated question-bank bridge","html":"<div class=\"bank-bridge\"><h2>More practice on the platform</h2><p>This lesson maps to <code>IBAI.U1.NUMBER, IBAI.U1.MODELING</code>. The attached private banks stay inside authenticated school access; no private prompt is copied into this public lesson file.</p><a href=\"https://2ed944-cloud.github.io/ECHS-Math/question-bank/practice.html?course=ib-math-ai&unit=1&lesson=1.1\" class=\"button-link\">Open additional bank practice</a></div>","kind":"launch","eyebrow":""}],"practice":[{"id":"IBAI-1.1-P01","level":"Foundation","prompt":"Write \\(0.000438\\) in standard form.","answer":"\\(4.38\\times10^{-4}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-4\\), so the result is \\(4.38\\times10^{-4}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["4.38e-4","4.38*10^-4","4.38x10^-4"]}},{"id":"IBAI-1.1-P02","level":"Foundation","prompt":"Write \\(72900000\\) in standard form.","answer":"\\(7.29\\times10^{7}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(7\\), so the result is \\(7.29\\times10^{7}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["7.29e7","7.29*10^7","7.29x10^7"]}},{"id":"IBAI-1.1-P03","level":"Foundation","prompt":"Write \\(0.00602\\) in standard form.","answer":"\\(6.02\\times10^{-3}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-3\\), so the result is \\(6.02\\times10^{-3}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["6.02e-3","6.02*10^-3","6.02x10^-3"]}},{"id":"IBAI-1.1-P04","level":"Foundation","prompt":"Write \\(905000000000\\) in standard form.","answer":"\\(9.05\\times10^{11}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(11\\), so the result is \\(9.05\\times10^{11}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["9.05e11","9.05*10^11","9.05x10^11"]}},{"id":"IBAI-1.1-P05","level":"Foundation","prompt":"Write \\(0.0000000817\\) in standard form.","answer":"\\(8.17\\times10^{-8}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-8\\), so the result is \\(8.17\\times10^{-8}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["8.17e-8","8.17*10^-8","8.17x10^-8"]}},{"id":"IBAI-1.1-P06","level":"Foundation","prompt":"Write \\(3.7\\times10^{5}\\) in ordinary notation.","answer":"\\(370000\\)","solution":"A power of \\(10^{5}\\) moves the decimal point 5 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":370000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P07","level":"Foundation","prompt":"Write \\(8.04\\times10^{-4}\\) in ordinary notation.","answer":"\\(0.000804\\)","solution":"A power of \\(10^{-4}\\) moves the decimal point 4 places left.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":0.0008039999999999999,"tolerance":5e-07}},{"id":"IBAI-1.1-P08","level":"Foundation","prompt":"Write \\(1.29\\times10^{7}\\) in ordinary notation.","answer":"\\(12900000\\)","solution":"A power of \\(10^{7}\\) moves the decimal point 7 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":12900000.0,"tolerance":1.29e-05}},{"id":"IBAI-1.1-P09","level":"Foundation","prompt":"Write \\(6.02\\times10^{-3}\\) in ordinary notation.","answer":"\\(0.00602\\)","solution":"A power of \\(10^{-3}\\) moves the decimal point 3 places left.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":0.006019999999999999,"tolerance":5e-06}},{"id":"IBAI-1.1-P10","level":"Foundation","prompt":"Write \\(9.9\\times10^{2}\\) in ordinary notation.","answer":"\\(990\\)","solution":"A power of \\(10^{2}\\) moves the decimal point 2 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":990.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P11","level":"Application","prompt":"Calculate \\((3.2\\times10^5)(4.5\\times10^{-3})\\).","answer":"\\(1.44\\times 10^{3}\\)","solution":"Multiply 3.2 by 4.5 and add exponents: \\(14.4\\times10^2=1.44\\times10^3\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":1440.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P12","level":"Application","prompt":"Calculate \\(\\frac{7.5\\times10^8}{2.5\\times10^3}\\).","answer":"\\(3\\times 10^{5}\\)","solution":"Divide coefficients and subtract exponents: \\(3\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":300000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P13","level":"Application","prompt":"Calculate \\((6.0\\times10^{-7})(8.0\\times10^{11})\\).","answer":"\\(4.8\\times 10^{5}\\)","solution":"\\(48\\times10^4=4.8\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":480000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P14","level":"Application","prompt":"Calculate \\(\\frac{9.6\\times10^{-4}}{3.2\\times10^2}\\).","answer":"\\(3\\times 10^{-6}\\)","solution":"\\(9.6/3.2=3\\) and \\(-4-2=-6\\), giving \\(3\\times10^{-6}\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":3e-06,"tolerance":5e-07}},{"id":"IBAI-1.1-P15","level":"Application","prompt":"Calculate \\(4.7\\times10^6+8.5\\times10^5\\).","answer":"\\(5.55\\times 10^{6}\\)","solution":"Rewrite \\(8.5\\times10^5=0.85\\times10^6\\), then add coefficients.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":5550000.0,"tolerance":5.55e-06}},{"id":"IBAI-1.1-P16","level":"Application","prompt":"Calculate \\(6.2\\times10^{-3}-7.5\\times10^{-4}\\).","answer":"\\(5.45\\times 10^{-3}\\)","solution":"Rewrite \\(7.5\\times10^{-4}=0.75\\times10^{-3}\\), giving \\(5.45\\times10^{-3}\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":0.00545,"tolerance":5e-06}},{"id":"IBAI-1.1-P17","level":"Application","prompt":"A satellite transmits \\(2.4\\times10^6\\) bits each second for \\(3.5\\times10^3\\) seconds. Find the total number of bits.","answer":"\\(8.4\\times 10^{9}\\)","solution":"Multiply rate by time: \\(8.4\\times10^9\\) bits.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":8400000000.0,"tolerance":0.0084}},{"id":"IBAI-1.1-P18","level":"Application","prompt":"A bacterial sample contains \\(7.2\\times10^8\\) cells divided equally among \\(3.0\\times10^2\\) containers. Find the cells per container.","answer":"\\(2.4\\times 10^{6}\\)","solution":"Divide total cells by containers: \\(2.4\\times10^6\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":2400000.0,"tolerance":2.4e-06}},{"id":"IBAI-1.1-P19","level":"Application","prompt":"A rectangular solar field is \\(1.8\\times10^3\\) m by \\(6.5\\times10^2\\) m. Find its area.","answer":"\\(1.17\\times 10^{6}\\)","solution":"Area is length × width: \\(11.7\\times10^5=1.17\\times10^6\\text{ m}^2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":1170000.0,"tolerance":1.17e-06}},{"id":"IBAI-1.1-P20","level":"Application","prompt":"A file has \\(4.0\\times10^7\\) records of \\(2.5\\times10^2\\) bytes each. Find the size in bytes.","answer":"\\(1\\times 10^{10}\\)","solution":"\\(4.0(2.5)\\times10^9=1.0\\times10^{10}\\) bytes.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":10000000000.0,"tolerance":0.01}},{"id":"IBAI-1.1-P21","level":"Reasoning","prompt":"Which quantity is greatest?","answer":"\\(7.9\\times10^6\\)","solution":"Compare exponents first. The only quantity with exponent 6 and coefficient 7.9 exceeds the other exponent-6 value.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(8.2\\times10^5\\)","\\(7.9\\times10^6\\)","\\(9.1\\times10^4\\)","\\(1.2\\times10^6\\)"],"correct":1},{"id":"IBAI-1.1-P22","level":"Reasoning","prompt":"Which is closest to \\(10^{-4}\\)?","answer":"\\(1.2\\times10^{-4}\\)","solution":"\\(1.2\\times10^{-4}\\) has the same order of magnitude and coefficient near 1.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(8.8\\times10^{-7}\\)","\\(1.2\\times10^{-4}\\)","\\(6.0\\times10^{-3}\\)","\\(9.0\\times10^{-2}\\)"],"correct":1},{"id":"IBAI-1.1-P23","level":"Reasoning","prompt":"The exponents of two positive quantities differ by 5. Their scale differs by approximately which factor?","answer":"\\(10^5\\)","solution":"A difference of 5 powers of ten corresponds to a factor of \\(10^5\\).","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["5","10","\\(10^5\\)","\\(5^{10}\\)"],"correct":2},{"id":"IBAI-1.1-P24","level":"Reasoning","prompt":"Which expression is already in normalized standard form?","answer":"\\(7.2\\times10^7\\)","solution":"Only \\(7.2\\) lies between 1 and 10.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(0.72\\times10^8\\)","\\(72\\times10^6\\)","\\(7.2\\times10^7\\)","\\(720\\times10^5\\)"],"correct":2},{"id":"IBAI-1.1-P25","level":"Reasoning","prompt":"Estimate \\(\\frac{6.2\\times10^7}{3.1\\times10^3}\\) using one significant figure, then state the exact standard-form value.","answer":"\\(2\\times 10^{4}\\)","solution":"Estimate \\(6/3\\times10^{4}=2\\times10^4\\). The exact quotient is also \\(2\\times10^4\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":20000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P26","level":"Reasoning","prompt":"A student writes \\(3.4\\times10^5+2.1\\times10^4=5.5\\times10^9\\). State the correct value.","answer":"\\(3.61\\times 10^{5}\\)","solution":"Use a common exponent: \\((3.4+0.21)\\times10^5=3.61\\times10^5\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":361000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P27","level":"Reasoning","prompt":"A population is \\(4.8\\times10^6\\), and a sample is \\(1.2\\times10^3\\). How many times larger is the population?","answer":"\\(4\\times 10^{3}\\)","solution":"Divide: \\((4.8/1.2)\\times10^{3}=4.0\\times10^3\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":4000,"tolerance":1e-06}},{"id":"IBAI-1.1-P28","level":"Reasoning","prompt":"A calculation gives \\(0.034\\times10^{-6}\\). Rewrite it in normalized standard form.","answer":"\\(3.4\\times 10^{-8}\\)","solution":"Move the decimal two places right and decrease the exponent by 2: \\(3.4\\times10^{-8}\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":3.4e-08,"tolerance":5e-10}},{"id":"IBAI-1.1-P29","level":"Reasoning","prompt":"Estimate \\((9.8\\times10^4)(2.1\\times10^{-6})\\) to one significant figure.","answer":"\\(0.2\\)","solution":"Use \\(10\\times2\\times10^{-2}=0.2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":0.2,"tolerance":0.05}},{"id":"IBAI-1.1-P30","level":"Reasoning","prompt":"Two masses are \\(2.5\\times10^{-6}\\) kg and \\(7.5\\times10^{-9}\\) kg. Find their ratio.","answer":"\\(333.333333\\)","solution":"The ratio is \\((2.5/7.5)\\times10^3=\\frac13\\times10^3\\approx333\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":333.3333333333,"tolerance":0.5}},{"id":"IBAI-1.1-P31","level":"Challenge","prompt":"A cube has edge \\(3.2\\times10^{-3}\\) m. Find its volume in \\(\\text{m}^3\\).","answer":"\\(3.2768\\times 10^{-8}\\)","solution":"Cube the coefficient and multiply exponent by 3: \\(32.768\\times10^{-9}=3.2768\\times10^{-8}\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":3.2768000000000006e-08,"tolerance":5e-11}},{"id":"IBAI-1.1-P32","level":"Challenge","prompt":"Light travels at \\(3.00\\times10^8\\) m/s. Estimate the distance travelled in 2.5 days.","answer":"\\(6.48\\times 10^{13}\\)","solution":"Convert 2.5 days to 216000 s, then multiply to obtain \\(6.48\\times10^{13}\\) m.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":64800000000000.0,"tolerance":50000000000.0}},{"id":"IBAI-1.1-P33","level":"Challenge","prompt":"A country uses \\(4.2\\times10^{11}\\) kWh yearly for \\(3.5\\times10^7\\) people. Find annual kWh per person.","answer":"\\(1.2\\times 10^{4}\\)","solution":"Divide to get \\(1.2\\times10^4\\) kWh per person.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":12000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P34","level":"Challenge","prompt":"A sphere has radius \\(6.0\\times10^{-5}\\) m. Using \\(V=\\frac43\\pi r^3\\), find its volume.","answer":"\\(9.0478\\times 10^{-13}\\)","solution":"Substitute without prematurely rounding: \\(V\\approx9.05\\times10^{-13}\\text{ m}^3\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":9.047786842338604e-13,"tolerance":2.261946710584651e-13}},{"id":"IBAI-1.1-P35","level":"Challenge","prompt":"Convert \\(7.5\\times10^8\\) mm to kilometres.","answer":"\\(750\\)","solution":"There are \\(10^6\\) mm in 1 km, so the answer is \\(7.5\\times10^2=750\\) km.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":750.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P36","level":"Challenge","prompt":"A sensor records \\(1.6\\times10^4\\) readings per second, each 24 bytes, for 30 days. Find the storage in bytes.","answer":"\\(9.9533\\times 10^{11}\\)","solution":"Multiply rate × bytes × seconds to get \\(9.95328\\times10^{11}\\) bytes.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":995328000000.0,"tolerance":2000000.995328}},{"id":"IBAI-1.1-P37","level":"Challenge","prompt":"A map uses scale \\(1:2.5\\times10^5\\). A route is \\(7.2\\times10^1\\) cm on the map. Find the real distance in km.","answer":"\\(180\\)","solution":"Real distance is \\(1.8\\times10^7\\) cm; divide by \\(10^5\\) cm/km to get 180 km.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":180.0,"tolerance":1e-06}},{"id":"IBAI-1.1-P38","level":"Challenge","prompt":"The density of a material is \\(7.8\\times10^3\\) kg/m³. Find the mass of \\(2.5\\times10^{-4}\\) m³.","answer":"\\(1.95\\)","solution":"Mass = density × volume = \\(1.95\\) kg.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":1.95,"tolerance":0.005}},{"id":"IBAI-1.1-P39","level":"Challenge","prompt":"A model estimates \\(6.4\\times10^9\\) events, each lasting \\(2.5\\times10^{-7}\\) s. Find total time in minutes.","answer":"\\(26.666667\\)","solution":"Total seconds are 1600; divide by 60 to obtain about 26.67 minutes.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":26.666666666666668,"tolerance":0.05}},{"id":"IBAI-1.1-P40","level":"Challenge","prompt":"Estimate the number of heartbeats in 80 years at 70 beats per minute. Give a standard-form estimate.","answer":"\\(2.9454\\times 10^{9}\\)","solution":"Multiply years × days × hours × minutes × beats to get about \\(2.95\\times10^9\\) beats.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":2945376000.0,"tolerance":24000.002945376}}],"quiz":[{"id":"IBAI-1.1-Q01","level":"Quiz","prompt":"Write \\(0.0000912\\) in standard form.","answer":"\\(9.12\\times10^{-5}\\)","solution":"Move the decimal five places right.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"text","accepted":["9.12e-5","9.12*10^-5","9.12x10^-5"]}},{"id":"IBAI-1.1-Q02","level":"Quiz","prompt":"Write \\(6.07\\times10^4\\) in ordinary notation.","answer":"\\(60700\\)","solution":"Move four places right.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":60700,"tolerance":1e-06}},{"id":"IBAI-1.1-Q03","level":"Quiz","prompt":"Calculate \\((2.8\\times10^6)(3.0\\times10^{-4})\\).","answer":"\\(8.4\\times 10^{2}\\)","solution":"Multiply coefficients and add exponents.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":839.9999999999999,"tolerance":1e-06}},{"id":"IBAI-1.1-Q04","level":"Quiz","prompt":"Calculate \\(\\frac{5.4\\times10^9}{9.0\\times10^2}\\).","answer":"\\(6\\times 10^{6}\\)","solution":"Divide coefficients and subtract exponents.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":6000000.0,"tolerance":6e-06}},{"id":"IBAI-1.1-Q05","level":"Quiz","prompt":"Calculate \\(7.1\\times10^5+4.4\\times10^4\\).","answer":"\\(7.54\\times 10^{5}\\)","solution":"Rewrite the second term as \\(0.44\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":754000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-Q06","level":"Quiz","prompt":"Which is larger: \\(8.9\\times10^{-3}\\) or \\(1.2\\times10^{-2}\\)? Enter 1 or 2.","answer":"2","solution":"The second has coefficient 1.2 at exponent −2, equal to 0.012.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2,"tolerance":1e-06}},{"id":"IBAI-1.1-Q07","level":"Quiz","prompt":"A sensor takes \\(1.5\\times10^4\\) readings per second for one hour. Find the number of readings.","answer":"\\(5.4\\times 10^{7}\\)","solution":"Multiply by 3600 seconds.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":54000000.0,"tolerance":5.4e-05}},{"id":"IBAI-1.1-Q08","level":"Quiz","prompt":"A total of \\(4.8\\times10^{12}\\) units is shared equally among \\(1.6\\times10^7\\) groups. Find units per group.","answer":"\\(3\\times 10^{5}\\)","solution":"Divide to obtain \\(3.0\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":300000.0,"tolerance":1e-06}},{"id":"IBAI-1.1-Q09","level":"Quiz","prompt":"A square has side \\(2.2\\times10^{-3}\\) m. Find its area.","answer":"\\(4.84\\times 10^{-6}\\)","solution":"Square coefficient and exponent.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":4.84e-06,"tolerance":5e-09}},{"id":"IBAI-1.1-Q10","level":"Quiz","prompt":"A process repeats \\(9.0\\times10^8\\) times at \\(2.4\\times10^{-6}\\) s each. Find total time in minutes.","answer":"\\(36\\)","solution":"Multiply to get seconds, then divide by 60.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":36.0,"tolerance":1e-06}}],"exam":[{"id":"IBAI-1.1-E01","style":"Paper 1-style short response","title":"Solar data archive","calculator":"GDC expected","total_marks":8,"context":"A satellite stores \\(3.6\\times10^5\\) images. Each image requires \\(2.4\\times10^6\\) bytes.","parts":[{"label":"a","prompt":"Calculate the total storage in bytes, giving your answer in standard form.","marks":2,"answer":"\\(8.64\\times10^{11}\\) bytes","markscheme":"M1 multiplies the two quantities and applies exponent law; A1 normalized result."},{"label":"b","prompt":"A compression system reduces storage by 37%. Find the compressed storage in bytes in standard form.","marks":2,"answer":"\\(5.4432\\times10^{11}\\) bytes","markscheme":"M1 uses multiplier 0.63; A1 correct value."},{"label":"c","prompt":"The archive is copied at \\(1.5\\times10^8\\) bytes per second. Find the transfer time in minutes.","marks":3,"answer":"\\(60.48\\) minutes","markscheme":"M1 divides storage by rate; A1 seconds \\(3628.8\\); A1 converts to minutes."},{"label":"d","prompt":"State one reason the calculated time may differ from real transfer time.","marks":1,"answer":"Protocol overhead, variable transfer rate or interruptions.","markscheme":"A1 one relevant modelling limitation."}]},{"id":"IBAI-1.1-E02","style":"Paper 2-style extended response","title":"Water-use estimation","calculator":"GDC expected","total_marks":10,"context":"A campus has 1450 people. A preliminary model assumes each person uses \\(1.8\\times10^2\\) L of water per day on 210 operating days each year.","parts":[{"label":"a","prompt":"Estimate annual water use in litres and write it in standard form.","marks":3,"answer":"\\(5.481\\times10^7\\) L","markscheme":"M1 forms \\(1450(180)(210)\\); A1 evaluates; A1 standard form with units."},{"label":"b","prompt":"Convert the answer to cubic metres, using \\(1\\text{ m}^3=10^3\\text{ L}\\).","marks":2,"answer":"\\(5.481\\times10^4\\text{ m}^3\\)","markscheme":"M1 divides by \\(10^3\\); A1 correct standard form."},{"label":"c","prompt":"A conservation plan targets a 12% reduction. Calculate the target annual use in cubic metres.","marks":2,"answer":"\\(48\\,232.8\\text{ m}^3\\)","markscheme":"M1 uses multiplier 0.88; A1 correct value."},{"label":"d","prompt":"Give two assumptions that should be tested before using the model for budgeting.","marks":2,"answer":"Examples: equal use per person; exactly 210 days; no leakage/irrigation variation; stable population.","markscheme":"A1 each for two distinct assumptions."},{"label":"e","prompt":"Explain why reporting the target to the nearest litre would be misleading.","marks":1,"answer":"The assumptions and input estimates do not justify that precision.","markscheme":"A1 links reporting precision to model uncertainty."}]}],"bankBridge":{"course":"ib-math-ai","unit":1,"lesson":"1.1","skillKeys":["IBAI.U1.NUMBER","IBAI.U1.MODELING"],"visibility":"authenticated-school-access","embeddedPrivatePrompts":false},"assessmentDesign":{"practiceLevels":{"Foundation":10,"Application":10,"Reasoning":10,"Challenge":10},"quizQuestions":10,"extendedTasks":2,"calculatorPolicy":"Technology is integrated throughout, with transparent setup and interpretation."}};
